from __future__ import annotations

from typing import Any

DEFAULT_STATE: dict[str, Any] = {
    "brief": {
        "site_name": "Northstar Studio",
        "business": "AI-native product studio",
        "tagline": "Ship ambitious software without the usual drag.",
        "audience": "technical founders and modern product teams",
        "visual_direction": "dark, premium, futuristic, restrained",
        "sections": "hero, proof, services, process, testimonials, pricing, faq, contact",
        "cta": "Start a project",
        "accent": "#8b5cf6",
        "refinement": "Make it feel polished, spacious, and credible.",
    },
    "generated": {},
    "build_history": [],
}

APP_JS = r'''(() => {
const root=document.getElementById("app");
let state={brief:{},generated:{},build_history:[]},tab="brief",busy=false,fileName="index.html";
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function req(action,payload={}){return new Promise((resolve,reject)=>{const requestId=crypto.randomUUID();const timer=setTimeout(()=>{window.removeEventListener("message",on);reject(new Error("Operly bridge timed out"));},300000);function on(e){const m=e.data||{};if(m.source!=="operly.temp-app.response"||m.requestId!==requestId)return;clearTimeout(timer);window.removeEventListener("message",on);m.ok?resolve(m.data):reject(new Error(m.error||"Operly action failed"));}window.addEventListener("message",on);parent.postMessage({source:"operly.temp-app",requestId,action,payload},"*");});}
function toast(msg,bad=false){const e=document.createElement("div");e.className="toast"+(bad?" bad":"");e.textContent=msg;document.body.appendChild(e);setTimeout(()=>e.remove(),3200);}
async function save(){await req("state.put",{state});}
const fields=[["site_name","Site name"],["business","What is the business?"],["tagline","Tagline"],["audience","Audience"],["visual_direction","Visual direction"],["sections","Sections"],["cta","Primary CTA"],["accent","Accent color"],["refinement","Build / refinement instruction"]];
const nav=()=>[["brief","Brief"],["preview","Live preview"],["files","Files"],["trace","Computer trace"],["history","Build history"]];
function shell(body){root.innerHTML=`<div class="shell"><aside><div class="brand"><div class="orb"></div><div><b>VIBE SITE BUILDER</b><span>Temporary computer-tools plugin</span></div></div><nav>${nav().map(([id,label])=>`<button data-tab="${id}" class="${tab===id?"active":""}">${label}</button>`).join("")}</nav><div class="stack"><span>REAL COMPUTER TOOLS</span><small>files.* · python.exec · terminal.exec · artifact.export</small></div></aside><main><header><div><span class="eyebrow">OPERLY PLUGIN · COMPUTER WORKFLOW TEST</span><h1>Vibe Site Builder</h1><p>Describe a site, then let one installed plugin use its isolated Sandbox computer to create, modify, inspect, validate and package a real HTML/CSS/JS project.</p></div><button class="primary" id="build">${busy?"Building…":"Build with Computer"}</button></header>${body}</main></div>`;document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.getElementById("build").onclick=build;}
function briefView(){const b=state.brief||{};shell(`<section class="grid2"><div class="panel"><div class="panel-head"><div><h2>Site brief</h2><p>This state is persisted in the plugin namespace.</p></div></div><div class="form">${fields.map(([k,l])=>`<label><span>${l}</span>${["refinement","visual_direction","sections"].includes(k)?`<textarea data-b="${k}">${esc(b[k]||"")}</textarea>`:`<input data-b="${k}" value="${esc(b[k]||"")}">`}</label>`).join("")}</div><div class="actions"><button class="ghost" id="saveBrief">Save brief</button><button class="primary" id="build2">${busy?"Building…":"Build site"}</button></div></div><div class="panel proof"><h2>What this build actually does</h2><ol><li>Creates a project directory with <b>files.mkdir</b>.</li><li>Writes the spec and starter files with <b>files.write</b>.</li><li>Runs a Python transformation with <b>python.exec</b> that modifies the HTML and produces build metadata.</li><li>Runs shell validation and ZIP packaging with <b>terminal.exec</b>.</li><li>Reads the generated files with <b>files.read</b>.</li><li>Exports the ZIP bundle with <b>artifact.export</b>.</li></ol><div class="proof-note">Everything runs in the same fresh network-off Sandbox VM. The plugin receives no Operly credentials.</div></div></section>`);document.querySelectorAll("[data-b]").forEach(i=>i.oninput=e=>{state.brief={...(state.brief||{}),[e.target.dataset.b]:e.target.value};});document.getElementById("saveBrief").onclick=async()=>{await save();toast("Brief saved");};document.getElementById("build2").onclick=build;}
function previewView(){const g=state.generated||{};shell(`<section class="panel"><div class="panel-head"><div><h2>Live preview</h2><p>${g.built_at?`Built ${esc(g.built_at)} · ${esc(g.report?.section_count??"")} sections`:"Run a computer build first."}</p></div>${g.bundle_base64?'<button class="ghost" id="download">Download ZIP</button>':""}</div>${g.preview_html?`<div class="browser"><div class="browserbar"><span></span><span></span><span></span><b>generated-site.local</b></div><iframe id="previewFrame" sandbox="allow-scripts"></iframe></div>`:`<div class="empty">No generated site yet.</div>`}</section>`);if(g.preview_html)document.getElementById("previewFrame").srcdoc=g.preview_html;const dl=document.getElementById("download");if(dl)dl.onclick=downloadZip;}
function filesView(){const files=(state.generated||{}).files||{};const names=Object.keys(files);if(!names.includes(fileName))fileName=names[0]||"index.html";shell(`<section class="panel files"><div class="file-list">${names.map(n=>`<button data-file="${esc(n)}" class="${fileName===n?"active":""}">${esc(n)}</button>`).join("")}</div><div class="editor"><div class="editor-head"><b>${esc(fileName)}</b><button class="ghost" id="saveFile">Save edit</button></div><textarea id="code">${esc(files[fileName]||"")}</textarea></div></section>`);document.querySelectorAll("[data-file]").forEach(b=>b.onclick=()=>{fileName=b.dataset.file;render();});const s=document.getElementById("saveFile");if(s)s.onclick=async()=>{state.generated={...(state.generated||{}),files:{...files,[fileName]:document.getElementById("code").value}};const f=state.generated.files;state.generated.preview_html=(f["index.html"]||"").replace(/<link[^>]*href=["'](?:assets\/)?styles\.css["'][^>]*>/i,`<style>${f["styles.css"]||""}</style>`).replace(/<script[^>]*src=["'](?:assets\/)?app\.js["'][^>]*><\/script>/i,`<script>${f["app.js"]||""}<\/script>`);await save();toast("Manual edit persisted");render();};}
function traceView(){const t=(state.generated||{}).trace||[];shell(`<section class="panel"><div class="panel-head"><div><h2>Computer trace</h2><p>${t.length} tool calls from the last build.</p></div></div><div class="trace">${t.map((x,i)=>`<div class="trace-row"><span>${i+1}</span><div><b>${esc(x.tool)}</b><small>${esc(x.summary||"")}</small></div><code>${esc(x.status||"ok")}</code></div>`).join("")||'<div class="empty">No build trace yet.</div>'}</div></section>`);}
function historyView(){const h=state.build_history||[];shell(`<section class="panel"><div class="panel-head"><div><h2>Build history</h2><p>Latest ten persisted builds.</p></div></div><div class="history">${h.map(x=>`<div><b>${esc(x.site_name)}</b><span>${esc(x.built_at)}</span><small>${esc(x.summary)}</small></div>`).join("")||'<div class="empty">No builds yet.</div>'}</div></section>`);}
function render(){({brief:briefView,preview:previewView,files:filesView,trace:traceView,history:historyView}[tab]||briefView)();}
async function build(){if(busy)return;busy=true;render();try{await save();toast("Fresh Sandbox computer starting…");const data=await req("capability.execute",{action:"analyze"});const r=data.result||data;if(!r.files||!r.preview_html)throw new Error("Builder returned an incomplete site");const item={site_name:state.brief?.site_name||"Untitled",built_at:r.built_at||new Date().toISOString(),summary:r.summary||"Build complete"};state.generated={files:r.files,preview_html:r.preview_html,trace:r.trace||[],report:r.report||{},bundle_base64:r.bundle_base64||"",bundle_sha256:r.bundle_sha256||"",built_at:item.built_at};state.build_history=[item,...(state.build_history||[])].slice(0,10);await save();tab="preview";toast("Computer build complete");}catch(e){toast(e.message||"Build failed",true);}finally{busy=false;render();}}
function downloadZip(){const b64=state.generated?.bundle_base64;if(!b64)return;const raw=atob(b64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const u=URL.createObjectURL(new Blob([bytes],{type:"application/zip"})),a=document.createElement("a");a.href=u;a.download=(state.brief?.site_name||"site").replace(/[^a-z0-9_-]+/gi,"-").toLowerCase()+".zip";a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function init(){root.innerHTML='<div class="boot">Opening Vibe Site Builder…</div>';try{const d=await req("state.get",{});state=d.state||state;render();}catch(e){root.innerHTML=`<div class="boot bad">${esc(e.message)}</div>`;}}
init();
})();'''

APP_CSS = r'''*{box-sizing:border-box}html,body,#app{margin:0;min-height:100%;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:#080a0f;color:#f7f8fb}button,input,textarea{font:inherit}.shell{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:100vh}aside{background:#0d1016;border-right:1px solid #232833;padding:18px 12px;display:flex;flex-direction:column;position:sticky;top:0;height:100vh}.brand{display:flex;gap:10px;align-items:center;padding:4px 7px 20px}.brand b{display:block;font-size:11px;letter-spacing:.1em}.brand span,.stack small{display:block;color:#707a89;font-size:10px;margin-top:3px}.orb{width:13px;height:13px;border-radius:50%;background:linear-gradient(135deg,#8b5cf6,#22d3ee);box-shadow:0 0 22px #8b5cf688}nav{display:grid;gap:5px}nav button,.file-list button{border:0;background:transparent;color:#98a1b0;text-align:left;padding:10px 11px;border-radius:9px;cursor:pointer}nav button.active,.file-list button.active{background:#1a1f28;color:#fff}.stack{margin-top:auto;padding:13px 8px;border-top:1px solid #242a35;color:#a78bfa;font-size:9px;letter-spacing:.1em}main{min-width:0;padding:32px 36px 60px;background:radial-gradient(circle at 80% -10%,#35215755,transparent 28%),#080a0f}header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;max-width:1400px;margin:0 auto 24px}header h1{font-size:34px;margin:5px 0 8px}header p,.panel p{color:#929aa8;line-height:1.55;max-width:780px;margin:0}.eyebrow{font-size:10px;letter-spacing:.14em;color:#a78bfa;font-weight:750}.primary,.ghost{border:1px solid #343b48;border-radius:9px;padding:9px 13px;background:#171b23;color:#e8ebf1;cursor:pointer}.primary{background:#7c3aed;border-color:#8b5cf6;color:#fff}.grid2{max-width:1400px;margin:auto;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:14px}.panel{max-width:1400px;margin:auto;border:1px solid #252b36;border-radius:16px;background:#0f131a;overflow:hidden}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:15px;border-bottom:1px solid #252b36;padding:17px 20px}.panel h2{margin:0 0 4px;font-size:18px}.form{padding:18px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.form label span{display:block;color:#8992a1;font-size:11px;margin-bottom:6px}.form input,.form textarea{width:100%;background:#090c11;border:1px solid #303744;border-radius:8px;color:#fff;padding:10px;min-height:40px}.form textarea{min-height:78px;resize:vertical}.actions{padding:0 18px 18px;display:flex;justify-content:flex-end;gap:8px}.proof{padding:20px}.proof ol{padding-left:22px;color:#c7ccd5;line-height:1.6}.proof li{margin:8px 0}.proof-note{margin-top:18px;border:1px solid #34304a;background:#171322;color:#b9a9ef;border-radius:10px;padding:12px;font-size:12px;line-height:1.45}.browser{margin:18px;background:#05070a;border:1px solid #2a303a;border-radius:14px;overflow:hidden}.browserbar{height:38px;background:#151a22;display:flex;align-items:center;gap:7px;padding:0 11px;color:#77808f;font-size:10px}.browserbar span{width:8px;height:8px;border-radius:50%;background:#434b58}.browserbar b{margin-left:8px;font-weight:500}.browser iframe{display:block;width:100%;height:680px;border:0;background:white}.files{display:grid;grid-template-columns:200px minmax(0,1fr);min-height:680px}.file-list{padding:12px;border-right:1px solid #252b36;display:grid;align-content:start;gap:4px}.editor{min-width:0}.editor-head{height:48px;padding:8px 12px;border-bottom:1px solid #252b36;display:flex;justify-content:space-between;align-items:center}.editor textarea{width:100%;height:630px;background:#090c11;color:#d7dce5;border:0;padding:16px;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;resize:none;outline:none}.trace{padding:10px}.trace-row{display:grid;grid-template-columns:32px 1fr auto;gap:10px;align-items:center;padding:12px;border-bottom:1px solid #202630}.trace-row>span{width:26px;height:26px;border-radius:8px;background:#1d2330;display:grid;place-items:center;font-size:11px;color:#9ca6b6}.trace-row b{display:block;font-size:12px}.trace-row small{display:block;margin-top:4px;color:#7e8796}.trace-row code{font-size:10px;color:#8ee0aa}.history{padding:10px}.history>div{display:grid;grid-template-columns:1fr auto;gap:4px;padding:13px;border-bottom:1px solid #202630}.history small{grid-column:1/-1;color:#7c8594}.history span{font-size:10px;color:#7c8594}.empty{padding:50px;text-align:center;color:#747d8b}.toast{position:fixed;right:18px;bottom:18px;background:#16251d;border:1px solid #346044;color:#b7f4ce;border-radius:10px;padding:11px 14px;z-index:50}.toast.bad,.boot.bad{background:#2a1717;border-color:#693737;color:#ffb5b5}.boot{min-height:100vh;display:grid;place-items:center;color:#9aa3b2}@media(max-width:820px){.shell{display:block}aside{height:auto;position:static;display:flex;flex-direction:row;align-items:center;overflow:auto;padding:10px}.brand{padding:0 8px;min-width:190px}.brand span,.stack{display:none}nav{display:flex;gap:4px;width:max-content}nav button{white-space:nowrap;padding:8px 9px}main{padding:20px 12px 45px}header{display:block}header h1{font-size:28px}header .primary{margin-top:14px}.grid2{grid-template-columns:1fr}.form{grid-template-columns:1fr}.browser{margin:10px}.browser iframe{height:520px}.files{display:block}.file-list{display:flex;overflow:auto;border-right:0;border-bottom:1px solid #252b36}.file-list button{white-space:nowrap}.editor textarea{height:520px}}'''

__all__ = ["DEFAULT_STATE", "APP_JS", "APP_CSS"]
